.chat-detail-screen .input-btn-mic {
  position: absolute !important;
  right: -40px !important;                /* 【调节】麦克风左右位置：相对于打字框右边缘的距离（负值越小越靠左，负值越大越靠右） */
  top: 50% !important;                    /* 【调节】麦克风上下位置：默认 50% 垂直居中 */
  transform: translateY(-50%) !important;
  width: 34px !important;                 /* 【调节】麦克风点击区宽度 */
  height: 34px !important;                /* 【调节】麦克风点击区高度 */
  background: transparent !important;
  border: none !important;
  padding: 0 !important;
  margin: 0 !important;
  z-index: 10 !important;
