/* ==========================================
   推文流聊天界面 - 修正版 (强制左对齐+紧凑+三点限制)
   ========================================== */

/* --- 1. 基础布局：干掉间距，强制所有消息靠左 --- */
.msg-bubble-wrapper {
  display: flex !important;
  /* 强制左右都是 row，这样用户消息的头像也会在左边 */
  flex-direction: row !important; 
  align-items: flex-start !important;
  justify-content: flex-start !important;
  padding: 0 8px !important;
  margin-bottom: 8px !important;
}

/* 强制去除原生气泡的一切外观和隐藏的 padding */
.msg-plain, .msg-bubble-container, .msg-content-stack {
  background: transparent !important;
  padding: 0.1px !important;
  margin: 0 !important;
  border: none !important;
  border-radius: 0 !important;
  box-shadow: none !important;
  color: #0f1419 !important;
  font-size: 15px !important;
  line-height: 1.5 !important;
  width: 100% !important;
  max-width: 100% !important;
}

/* 覆盖素净模式自带的左右留白变量，防止它把用户消息往右推 */
:root {
  --plain-padding-left-me: 0px;
  --plain-padding-right-me: 0px;
  --plain-padding-left-them: 0px;
  --plain-padding-right-them: 0px;
  --plain-content-max-width: 100%;
}

/* --- 2. 头像与内容区排版 (强制靠左修正版) --- */
/* 确保头像始终在最左边 */
.msg-avatar-me-container {
  margin-right: 10px !important;
  margin-left: 0 !important; /* 干掉可能存在的向右推的 margin */
  margin-top: 0px !important;
  flex-shrink: 0 !important;
  order: 1; 
}

.msg-content-stack {
  order: 2; 
  position: relative !important;
  margin-left: 0 !important;
  margin-right: auto !important; /* 把所有弹簧挤到右边，自己死死靠左 */
  align-items: flex-start !important; /* 强制内部文字、气泡全部左对齐 */
  text-align: left !important;
}

/* 针对用户消息做最严厉的左对齐限制 */
.msg-me {
  justify-content: flex-start !important;
}
.msg-me .msg-content-stack {
  align-items: flex-start !important;
  text-align: left !important;
  margin-left: 0 !important;
