/* 替换之前的 .msg-reply-detached-text 相关代码 */

.msg-reply-detached-text {
  display: block !important;
  width: auto !important;
  position: relative !important; 
  background-color: rgba(29, 155, 240, 0.15) !important; 
  color: #0f1419 !important; 
  padding: 2px 2px !important; 
  font-size: 13px !important; /* 👈 字体改小了！ */
  line-height: 1.5 !important;
  white-space: normal !important;
  overflow: visible !important; 

  /* 👇 用实线边框代替之前的多重背景画线 */
  border-left: 1.5px solid #1d9bf0 !important;
  border-right: 1.5px solid #1d9bf0 !important;
}

/* 👇 重构左侧伪元素：本体是左上角圆点，用 box-shadow 画左下角圆点 */
.msg-reply-detached-text::before {
  content: "" !important;
  position: absolute !important;
  left: -5px !important; /* 2px边框的一半(1px) + 自身一半(4px) = 5px */
  top: -4px !important; /* 稍微往上凸出一点 */
  width: 8px !important;
  height: 8px !important;
  background-color: #1d9bf0 !important;
  border-radius: 50% !important; /* 👈 纯圆！绝对方不了！ */
  z-index: 10 !important;
}

/* 👇 重构右侧伪元素：本体是右上角圆点，用 box-shadow 画右下角圆点 */
.msg-reply-detached-text::after {
  content: "" !important;
  position: absolute !important;
  right: -5px !important; 
  bottom: -3px !important;
  width: 8px !important;
  height: 8px !important;
  background-color: #1d9bf0 !important;
  border-radius: 50% !important;
  z-index: 10 !important;
}

/* ==========================================
   翻译内容：透明底 + 纯正外描边贴纸字
   ========================================== */

/* 1. 隐藏翻译按钮并默认展开翻译 */
:root {
  translation-always-show: 1;
  translation-btn-display: none;
  translation-bg: transparent;
  translation-padding: 0;
  translation-margin: 6px 0 0 0;
  translation-border: none;
  translation-shadow: none;
  translation-separator: none;
}

.msg-translation-btn {
  display: none !important;
}

/* 2. 翻译文字：先画描边再填白芯，绝不吃字 */
.msg-translation-content,
.msg-translation-detached-content {
  background: transparent !important;
  padding: 2px 4px !important; /* 给外描边留一点呼吸空间防裁切 */
  border: none !important;
  box-shadow: none !important;
  margin-top: -10px !important;
  margin-left: 10px !important;


  font-family: "Hiragino Sans", "PingFang SC", "Microsoft YaHei", -apple-system, BlinkMacSystemFont, sans-serif !important;
  font-weight: 500 !important;
  font-size: 12px !important;
  line-height: 1.5 !important;
  letter-spacing: 0.5px !important;

  /* 核心：白字填充 */
  color: #ffffff !important;
  -webkit-text-fill-color: #ffffff !important;

  /* 核心神技：先画描边再画填充，变成纯外描边！粗细可以大胆调到 3px~4px */
  paint-order: stroke fill !important;
  -webkit-text-stroke: 2.5px #1d9bf0 !important;
  stroke-linejoin: round !important;

  /* 兜底补强：用一圈同色硬阴影把笔画交界处的死角填圆润 */
  text-shadow:
    0 1px 0 #1d9bf0,
    0 -1px 0 #1d9bf0,
    1px 0 0 #1d9bf0,
    -1px 0 0 #1d9bf0 !important;
}

/* ==========================================
   语音气泡美化：Spotify 歌曲卡片风格
   ========================================== */

/* 1. 卡片外壳：固定宽度 + 半透明背景 */
.voice-msg {
  width: 280px !important; /* 固定宽度，可根据喜好微调 */
  max-width: 100% !important;
  background: rgba(255, 255, 255, 0.4) !important; /* 半透明白底 */
  backdrop-filter: blur(10px) !important;
  -webkit-backdrop-filter: blur(10px) !important;
  border-radius: 8px !important;
  padding: 10px 12px !important;
  box-sizing: border-box !important;
  border: 1px solid rgba(0, 0, 0, 0.05) !important;
  display: flex !important;
  flex-direction: column !important;
}

/* 2. 隐藏原生声纹图 */
.voice-waveform {
  display: none !important;
}

/* 3. 控制行布局 (封面 + 文字 + 时间) */
.voice-controls-row {
  position: relative !important;
  display: flex !important;
  align-items: center !important;
  justify-content: flex-start !important; /* 从左往右排 */
  gap: 12px !important; /* 封面和文字之间固定留12px */
  width: 100% !important;
}

/* 4. 左侧播放键变“封面图” */
.voice-play-btn {
  width: 48px !important;
  height: 48px !important;
  background-color: #e1e8ed !important;

  /* 👇 在这里替换为你预留的图片 URL 👇 */
  background-image: url('https://bu.dusays.com/2026/11/17/6afb362e0a06c.jpg') !important;
  background-size: cover !important;
  background-position: center !important;

  border-radius: 6px !important;
  border: none !important;
  box-shadow: 0 2px 5px rgba(0,0,0,0.1) !important;
  flex-shrink: 0 !important;
  z-index: 2 !important;
}

/* 隐藏播放键原本的三角形 SVG */
.voice-play-btn svg {
  display: none !important;
}

/* 2. 彻底干掉波形里的所有垃圾占位元素 */
.voice-waveform > * {
  display: none !important;
}

/* 3. 借用波形容器写两行文字，强制去除任何原生间距 */
.voice-waveform {
  display: flex !important; 
  flex-direction: column !important;
  justify-content: center !important;
  align-items: flex-start !important; /* 文字全部靠左 */
  flex: 1 !important; 
  height: 48px !important; 
  padding: 0 !important; 
  margin: 0 !important;

  /* 重点：清空原生可能自带的强行换行或拉伸 */
  line-height: 1.2 !important; 
}

/* 自定义文案：第一行：深灰 */
.voice-waveform::before {
  content: "Celestial Bliss"; 
  color: #0f1419 !important;
  font-size: 14px !important;
  font-weight: 600 !important;
  font-family: -apple-system, BlinkMacSystemFont, sans-serif !important;
  margin: 0 0 2px 0 !important; /* 只留 2px 的紧凑间距 */
  padding: 0 !important;
}

/* 自定义文案：第二行：中灰 */
.voice-waveform::after {
  content: "One star, one heart"; 
  color: #536471 !important;
  font-size: 12px !important;
  font-family: -apple-system, BlinkMacSystemFont, sans-serif !important;
  margin: 0 !important;
  padding: 0 !important;
}

/* 6. 语音时间固定在右侧 */
.voice-duration {
  font-size: 12px !important;
  color: #536471 !important;
  font-weight: 400 !important;
  position: absolute !important;
  right: 10px !important;
  bottom: 15px !important;
}

/* 7. 底部链接：open.spotify.com */
.voice-transcription-toggle {
  font-size: 0 !important; /* 干掉原本的文字（查看/隐藏） */
  color: transparent !important;
  display: inline-flex !important;
  align-items: center !important;
  margin-top: 8px !important;
  padding: 0 !important;
}

/* 隐藏原本的星星 SVG */
.voice-transcription-toggle svg {
  display: none !important;
}

/* 用伪元素画出 Spotify Logo + 链接文字 */
.voice-transcription-toggle::before {
  content: "open.spotify.com";
  font-size: 11px !important;
  color: #96cdf2 !important; /* 浅 X 蓝 */
  text-decoration: underline !important;
  font-family: sans-serif !important;

  /* 垫入 Spotify SVG 图标 */
