/* ==========================================
   文字图美化：紧凑版推特嵌套风格
   ========================================== */

/* 1. 外壳：拉宽并往左偏移，画一条贯穿的竖线 */
.msg-sim-card {
  min-width: 280px !important;
  background: transparent !important;
  border: none !important;
  box-shadow: none !important;
  padding: 0 !important;
  margin-top: -120px !important;
  bottom: -100px !important;
  margin-bottom: 0px !important;
  margin-left: -45.5px !important; /* 整体左移，让假头像和真头像垂直对齐 */
  position: relative !important;
  overflow: visible !important;

  /* 魔法：画一条贯穿全高的淡灰色竖线 (在 18px 处) */
  background-image: linear-gradient(to right, transparent 17px, #cfd9de 17px, #cfd9de 19px, transparent 19px) !important;
  background-repeat: no-repeat !important;
  background-size: 100% 38% !important;
  background-position: 0px 38px !important;
}

/* 隐藏原生多余内容 */
.msg-sim-card > * {
  display: none !important;
}

