    url('https://bu.dusays.com/2026/11/19/6afdd3a028a98.jpg') !important;

  background-size: 
  calc(50% - 1px) 130px,  /* 左图：强制正方形 */
    calc(50% - 1px) 130px !important; 

  background-position: 
    left top, 
    right top !important;

  background-repeat: no-repeat !important;
}

